    if (!design || !designStore || selectedDesignPieceGuidsForCommands.length === 0) return;
    transaction?.start();
    try {
      await designStore.execute("compose.designApp.fixPieces", getOrigin(), selectedDesignPieceGuidsForCommands);
    } finally {
      transaction?.finalize();
    }
  };
```

